function Invoke-Guard {
 param([string]$Label,[string[]]$Vector,[string]$Expected,[string]$Output,[string]$Mode='producer',[bool]$ExpectExisting=$false)
 $dir=Join-Path $guardRoot $Label;if(Test-Path $dir){if($Label -ne 'existing-output'){throw "Guard evidence exists, refusing overwrite: $Label"}}else{[IO.Directory]::CreateDirectory($dir)|Out-Null}
 if($Mode -eq 'producer' -and ($Vector.Count -ne 5 -or $Vector[3] -ne '-P' -or $Vector[4] -ne $producerScript)){throw "Producer guard argv failed: $Label"}
 [IO.File]::WriteAllText((Join-Path $dir 'argv.json'),(@{executable=$cmake;workingDirectory=$dir;arguments=$Vector}|ConvertTo-Json -Depth 4),[Text.UTF8Encoding]::new($false))
 $psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName=$cmake;$psi.WorkingDirectory=$dir;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;foreach($a in $Vector){[void]$psi.ArgumentList.Add($a)}
 $p=[Diagnostics.Process]::new();$p.StartInfo=$psi;$sw=[Diagnostics.Stopwatch]::StartNew();if(-not $p.Start()){throw "Process failed to start: $Label"};$ot=$p.StandardOutput.ReadToEndAsync();$et=$p.StandardError.ReadToEndAsync();$p.WaitForExit();$exit=$p.ExitCode;$sw.Stop();$out=$ot.GetAwaiter().GetResult();$err=$et.GetAwaiter().GetResult();[IO.File]::WriteAllText((Join-Path $dir 'stdout.log'),$out,[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $dir 'stderr.log'),$err,[Text.UTF8Encoding]::new($false));$matched=($out+"`n"+$err).Contains($Expected);$exists=Test-Path -LiteralPath $Output
 $r=[ordered]@{case=$Label;exitCode=$exit;elapsedSeconds=[Math]::Round($sw.Elapsed.TotalSeconds,3);expectedDiagnostic=$Expected;diagnosticMatched=$matched;output=$Output;outputExists=$exists;outputWasExpectedExisting=$ExpectExisting};[IO.File]::WriteAllText((Join-Path $dir 'result.json'),($r|ConvertTo-Json -Depth 4),[Text.UTF8Encoding]::new($false));if($exit -eq 0 -or !$matched -or (!$ExpectExisting -and $exists) -or ($ExpectExisting -and !$exists)){throw "Guard failed clean refusal: $Label exit=$exit matched=$matched outputExists=$exists"};return [pscustomobject]$r
}
